function sldRecord(areaFa, areaEn, icd, aCriteria) {
  return {
    nameFa: `\u0627\u062E\u062A\u0644\u0627\u0644 \u06CC\u0627\u062F\u06AF\u06CC\u0631\u06CC \u062E\u0627\u0635 \u2014 ${areaFa}`,
    nameEn: areaEn,
    icd,
    criteria: [
      ...aCriteria,
      { id: "sld.b", group: "B", textFa: "\u0645\u0647\u0627\u0631\u062A\u200C\u0647\u0627\u06CC \u0622\u0633\u06CC\u0628\u200C\u062F\u06CC\u062F\u0647 \u0628\u0647\u200C\u0637\u0648\u0631 \u0645\u0644\u0645\u0648\u0633 \u0648 \u0642\u0627\u0628\u0644\u200C\u0633\u0646\u062C\u0634 \u067E\u0627\u06CC\u06CC\u0646\u200C\u062A\u0631 \u0627\u0632 \u0627\u0646\u062A\u0638\u0627\u0631 \u0633\u0646 \u0627\u0633\u062A \u0648 \u062F\u0631 \u0639\u0645\u0644\u06A9\u0631\u062F (\u0645\u062F\u0631\u0633\u0647/\u06A9\u0627\u0631/\u0632\u0646\u062F\u06AF\u06CC \u0631\u0648\u0632\u0627\u0646\u0647) \u0627\u062E\u062A\u0644\u0627\u0644 \u0627\u06CC\u062C\u0627\u062F \u0645\u06CC\u200C\u06A9\u0646\u062F." },
      { id: "sld.c", group: "C", textFa: "\u062F\u0634\u0648\u0627\u0631\u06CC \u0627\u0632 \u0633\u0627\u0644\u200C\u0647\u0627\u06CC \u0627\u0648\u0644 \u0622\u0645\u0648\u0632\u0634 \u0631\u0633\u0645\u06CC \u0634\u0631\u0648\u0639 \u0634\u062F\u0647\u061B \u0627\u0644\u0628\u062A\u0647 \u0645\u0645\u06A9\u0646 \u0627\u0633\u062A \u0628\u0627 \u0631\u0627\u0647\u06A9\u0627\u0631\u0647\u0627\u06CC \u062C\u0628\u0631\u0627\u0646\u06CC \u062A\u0627 \u0628\u0627\u0644\u0627\u062A\u0631 \u0627\u0632 \u0622\u0646 \u0622\u0634\u06A9\u0627\u0631 \u0646\u0634\u062F\u0647 \u0628\u0627\u0634\u062F." },
      { id: "sld.d", group: "D", textFa: "\u0628\u0647\u062A\u0631 \u0627\u0633\u062A \u0628\u0627 \u0646\u0627\u0631\u0633\u0627\u06CC\u06CC \u0641\u06A9\u0631\u06CC\u060C \u0627\u062E\u062A\u0644\u0627\u0644 \u062D\u0633\u06CC (\u0628\u06CC\u0646\u0627\u06CC\u06CC/\u0634\u0646\u0648\u0627\u06CC\u06CC)\u060C \u0646\u0628\u0648\u062F \u0622\u0645\u0648\u0632\u0634 \u06A9\u0627\u0641\u06CC \u06CC\u0627 \u0632\u0628\u0627\u0646 \u062F\u0648\u0645 \u062A\u0648\u0636\u06CC\u062D \u062F\u0627\u062F\u0647 \u0646\u0634\u0648\u062F." }
    ],
    durationFa: "\u062F\u0634\u0648\u0627\u0631\u06CC \u062D\u062F\u0627\u0642\u0644 \u06F6 \u0645\u0627\u0647 \u0627\u0633\u062A \u0648 \u0628\u0627 \u0645\u062F\u0627\u062E\u0644\u0647\u0654 \u0647\u062F\u0641\u0645\u0646\u062F \u0647\u0645 \u0628\u0627\u0642\u06CC \u0645\u06CC\u200C\u0645\u0627\u0646\u062F.",
    onsetFa: "\u0627\u0632 \u0633\u0627\u0644\u200C\u0647\u0627\u06CC \u0627\u0648\u0644 \u0622\u0645\u0648\u0632\u0634 \u0645\u062F\u0631\u0633\u0647 (\u0634\u0631\u0648\u0639\u06CC \u2014 \u062D\u062A\u06CC \u0627\u06AF\u0631 \u062C\u0628\u0631\u0627\u0646 \u06A9\u0631\u062F\u0647 \u0628\u0627\u0634\u062F).",
    exclusionsFa: ["\u0646\u0627\u0631\u0633\u0627\u06CC\u06CC \u0641\u06A9\u0631\u06CC", "\u0627\u062E\u062A\u0644\u0627\u0644 \u062D\u0633\u06CC \u062A\u0634\u062E\u06CC\u0635\u200C\u062F\u0627\u062F\u0647\u200C\u0634\u062F\u0647", "\u0622\u0645\u0648\u0632\u0634 \u0646\u0627\u06A9\u0627\u0641\u06CC \u06CC\u0627 \u0641\u0631\u0635\u062A \u06A9\u0645"],
    referralFa: ["\u0627\u0631\u0632\u06CC\u0627\u0628\u06CC \u062A\u062E\u0635\u0635\u06CC \u0631\u0648\u0627\u0646\u200C\u0633\u0646\u062C\u06CC (\u0647\u0648\u0634 + \u0639\u0645\u0644\u06A9\u0631\u062F \u062A\u062D\u0635\u06CC\u0644\u06CC) \u0628\u0631\u0627\u06CC \u0642\u0637\u0639\u06CC\u062A", "\u062F\u0631 \u0635\u0648\u0631\u062A \u0634\u06A9 \u0628\u0647 \u0645\u0634\u06A9\u0644 \u062D\u0633\u06CC: \u0627\u0631\u062C\u0627\u0639 \u0686\u0634\u0645\u200C\u067E\u0632\u0634\u06A9\u06CC/\u0634\u0646\u0648\u0627\u06CC\u06CC"]
  };
}
