      { title: "\u06A9\u0627\u0631\u0650 \u06A9\u0648\u062A\u0627\u0647 \u0628\u0627 \u062A\u0627\u06CC\u0645\u0631 \u0628\u0635\u0631\u06CC", description: "\u06A9\u0627\u0631 \u0631\u0627 \u0628\u0627\u0632\u0647\u200C\u0647\u0627\u06CC \u06F5 \u062A\u0627 \u06F1\u06F0 \u062F\u0642\u06CC\u0642\u0647\u200C\u0627\u06CC \u0628\u0627 \u062A\u0627\u06CC\u0645\u0631 \u0634\u0646\u06CC/\u0628\u0635\u0631\u06CC\u061B \u0648\u0642\u0641\u0647\u0654 \u062D\u0631\u06A9\u062A\u06CC \u06A9\u0648\u062A\u0627\u0647 \u0628\u06CC\u0646 \u0628\u0627\u0632\u0647\u200C\u0647\u0627.", minutes: 10 },
      { title: "\u062F\u0633\u062A\u0648\u0631\u0650 \u06CC\u06A9\u200C\u0645\u0631\u062D\u0644\u0647\u200C\u0627\u06CC", description: "\u06CC\u06A9 \u062F\u0633\u062A\u0648\u0631 \u062F\u0631 \u0647\u0631 \u0628\u0627\u0631\u060C \u0628\u0627 \u062A\u0645\u0627\u0633 \u0686\u0634\u0645\u06CC \u0648 \u062A\u0623\u06CC\u06CC\u062F\u0650 \u0634\u0646\u06CC\u062F\u0646\u061B \u0628\u0639\u062F \u0645\u0631\u062D\u0644\u0647\u0654 \u0628\u0639\u062F.", minutes: 5 },
      { title: "\u0686\u06A9\u200C\u0644\u06CC\u0633\u062A \u062A\u06CC\u06A9\u200C\u062F\u0627\u0631", description: "\u06A9\u0627\u0631\u0647\u0627\u06CC \u0631\u0648\u0632 \u0631\u0648\u06CC \u0686\u06A9\u200C\u0644\u06CC\u0633\u062A \u062F\u06CC\u062F\u0627\u0631\u06CC\u061B \u0647\u0631 \u062A\u06CC\u06A9\u060C \u0628\u0627\u0632\u062E\u0648\u0631\u062F \u0641\u0648\u0631\u06CC \u0648 \u0645\u0634\u062E\u0635.", minutes: 5 }
