      means: "\u0627\u0644\u06AF\u0648\u06CC \u062A\u0648\u062C\u0647/\u062A\u06A9\u0627\u0646\u0634\u06AF\u0631\u06CC \u062F\u0631 \u062F\u0648 \u0645\u062D\u06CC\u0637 \u0628\u0631\u0631\u0633\u06CC \u0645\u06CC\u200C\u0634\u0648\u062F\u061B \u0633\u0627\u062E\u062A\u0627\u0631 \u0648 \u0628\u0627\u0632\u062E\u0648\u0631\u062F \u0641\u0648\u0631\u06CC\u060C \u0642\u0631\u0636\u200C\u062F\u0627\u062F\u0646 \u0645\u062F\u06CC\u0631\u06CC\u062A \u062A\u0648\u062C\u0647 \u0627\u0633\u062A.",
      next: "\u0627\u06AF\u0631 \u0641\u0642\u0637 \u06CC\u06A9 \u0641\u0631\u0645 \u067E\u0631 \u0634\u062F\u0647\u060C \u0641\u0631\u0645 \u0645\u0631\u062C\u0639 \u062F\u0648\u0645 \u0631\u0627 \u0628\u0641\u0631\u0633\u062A\u06CC\u062F\u061B \u0645\u0644\u0627\u06A9 \u062F\u0648 \u0645\u062D\u06CC\u0637 \u0631\u0627 \u062D\u062A\u0645\u0627\u064B \u0628\u0633\u0646\u062C\u06CC\u062F."
