    title: "\u0633\u0627\u0632\u06AF\u0627\u0631\u06CC \u0628\u0627 \u062A\u063A\u06CC\u06CC\u0631 \u0645\u0642\u0637\u0639",
    coreDeficit: "\u0641\u0634\u0627\u0631 \u0645\u062D\u06CC\u0637 \u0648 \u0627\u0646\u062A\u0638\u0627\u0631\u0627\u062A \u062C\u062F\u06CC\u062F",
